import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
const KEY = 'ernestdefoe-testimonials.aspects';
const t = (key, params = {}) => app.translator.trans(`ernestdefoe-testimonials.admin.aspects.${key}`, params);
/**
 * The rated aspects ("Customer service", "Quality"…): add, rename, reorder, remove. Ids never
 * change, so a rename keeps every rating given; a removed aspect stops showing and its ratings stay.
 * Saved with the page's other settings (it writes the JSON into the page's setting stream).
 */
export default class Aspects extends Component {
  stream() {
    return this.attrs.page.setting(KEY);
  }
  list() {
    try {
      const raw = this.stream()();
      const parsed = JSON.parse(raw === undefined || raw === null || raw === '' ? '[]' : raw);
      return Array.isArray(parsed) ? parsed.filter(a => a && a.id && typeof a.name === 'string') : [];
    } catch (e) {
      return [];
    }
  }
  write(list) {
    this.stream()(JSON.stringify(list));
  }
  view() {
    const list = this.list();
    const nextId = list.reduce((max, a) => Math.max(max, Number(a.id)), 0) + 1;
    return m("div", {
      className: "Form-group TestimonialsAspects"
    }, m("label", null, t('label')), m("p", {
      className: "helpText"
    }, t('help')), m("ol", {
      className: "TestimonialsAspects-list"
    }, list.map((aspect, i) => this.row(list, aspect, i))), m(Button, {
      className: "Button",
      icon: "fas fa-plus",
      onclick: () => {
        list.push({
          id: nextId,
          name: ''
        });
        this.write(list);
      }
    }, t('add')));
  }

  /** One aspect: its name, move it up, remove it. Every change writes the whole list back. */
  row(list, aspect, i) {
    const label = (key, params = {}) => app.translator.trans(`ernestdefoe-testimonials.admin.aspects.${key}`, params, true);
    return m("li", {
      key: aspect.id
    }, m("input", {
      className: "FormControl",
      value: aspect.name,
      maxlength: 60,
      "aria-label": label('name', {
        index: i + 1
      }),
      oninput: e => {
        list[i] = {
          ...aspect,
          name: e.target.value
        };
        this.write(list);
      }
    }), m(Button, {
      className: "Button Button--icon",
      icon: "fas fa-arrow-up",
      disabled: i === 0,
      "aria-label": label('up'),
      onclick: () => {
        [list[i - 1], list[i]] = [list[i], list[i - 1]];
        this.write(list);
      }
    }), m(Button, {
      className: "Button Button--icon",
      icon: "fas fa-trash-can",
      "aria-label": label('remove'),
      onclick: () => {
        list.splice(i, 1);
        this.write(list);
      }
    }));
  }
}